package com.wms.model.entity;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="purchase_request_lines") public class PurchaseRequestLine { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false,fetch=FetchType.LAZY) private PurchaseRequest request; @ManyToOne(optional=false,fetch=FetchType.LAZY) private Item item; @Column(nullable=false,precision=18,scale=4) private BigDecimal currentStock=BigDecimal.ZERO; @Column(nullable=false,precision=18,scale=4) private BigDecimal suggestedQuantity; @Column(nullable=false,precision=18,scale=4) private BigDecimal quantity; @Column(precision=18,scale=4) private BigDecimal unitPrice=BigDecimal.ZERO; private String remark; public Long getId(){return id;} public PurchaseRequest getRequest(){return request;} public void setRequest(PurchaseRequest v){request=v;} public Item getItem(){return item;} public void setItem(Item v){item=v;} public BigDecimal getCurrentStock(){return currentStock;} public void setCurrentStock(BigDecimal v){currentStock=v;} public BigDecimal getSuggestedQuantity(){return suggestedQuantity;} public void setSuggestedQuantity(BigDecimal v){suggestedQuantity=v;} public BigDecimal getQuantity(){return quantity;} public void setQuantity(BigDecimal v){quantity=v;} public BigDecimal getUnitPrice(){return unitPrice;} public void setUnitPrice(BigDecimal v){unitPrice=v;} public String getRemark(){return remark;} public void setRemark(String v){remark=v;} }
